ValidationRule.errorConditionFormula:
AND(
    RecordType.DeveloperName = "Cloud_uAssist_Order",
    $Permission.Block_InProgress_Update,
    ISCHANGED(uAssist_Status__c),

    OR(
        /* Condition 1 */
        AND(
            OR(
                ISPICKVAL(PRIORVALUE(uAssist_Status__c), "Ready to QC"),
                ISPICKVAL(PRIORVALUE(uAssist_Status__c), "Rework Required"),
                ISPICKVAL(PRIORVALUE(uAssist_Status__c), "QC in Progress")
            ),
            ISPICKVAL(uAssist_Status__c, "In Progress")
        ),

        /* Condition 2 */
        OR(
            ISPICKVAL(uAssist_Status__c, "Ready to QC"),
            ISPICKVAL(uAssist_Status__c, "Rework Required"),
            ISPICKVAL(uAssist_Status__c, "QC in Progress")
        )
    )
)
